//! Daily CHIRPS v3.0 preliminary precipitation (UCSB Climate Hazards Center):
//! one global 0.05° GeoTIFF per day (7200 x 2400, LZW float32, 60°S–60°N), published
//! ~2 days after each 5-day pentad ends (so the freshest day is typically 2–7 days old).
//! Each day is subset to a Peru window, stored as a compact binary grid, and aggregated
//! to daily department means via a committed mask (static/geo/peru_mask.bin, generated by
//! tools/make_peru_mask.py from Natural Earth 10m admin-1).

use crate::db;
use crate::fetch::{self, Ctx, Fetched};
use crate::grid::Grid;
use anyhow::{Context, Result, bail};
use chrono::{Duration, NaiveDate};
use rusqlite::params;
use serde::Deserialize;
use std::collections::HashSet;
use std::io::Cursor;
use std::path::PathBuf;
use std::sync::OnceLock;

pub const DATASET: &str = "chirps";
const BASE: &str = "https://data.chc.ucsb.edu/products/CHIRPS/v3.0/daily/prelim/sat";
/// Frames downloaded per scheduled run (each is ~11 MB).
const PER_RUN: usize = 6;
/// How many days back we probe for the newest published frame.
const PROBE_DAYS: i64 = 12;

// Global CHIRPS v3 grid; validated against the TIFF tags at parse time.
const FULL_NCOLS: usize = 7200;
const FULL_NROWS: usize = 2400;
const CELL: f64 = 0.05;
const FULL_LON0: f64 = -179.975; // centre of column 0
const FULL_LAT_TOP: f64 = 59.975; // centre of row 0

// ---------------------------------------------------------------- mask & metadata

#[derive(Debug, Clone)]
pub struct Department {
    pub code: String,
    pub name_es: String,
    pub name_en: String,
}

#[derive(Deserialize)]
struct DeptJson {
    code: String,
    name_es: String,
    name_en: String,
}

#[derive(Deserialize)]
struct WindowJson {
    cell: f64,
    ncols: usize,
    nrows: usize,
    lon0: f64,
    lat_top: f64,
}

#[derive(Deserialize)]
struct MetaJson {
    window: WindowJson,
    departments: Vec<DeptJson>,
}

struct Mask {
    departments: Vec<Department>,
    ncols: usize,
    nrows: usize,
    lon0: f64,
    lat_top: f64,
    /// Per cell (row-major, row 0 = northernmost): department index or 255 = outside Peru.
    bytes: &'static [u8],
}

static MASK: OnceLock<Mask> = OnceLock::new();

fn mask() -> &'static Mask {
    MASK.get_or_init(|| {
        let meta: MetaJson =
            serde_json::from_str(include_str!("../../static/geo/peru_departments.json"))
                .expect("peru_departments.json parses");
        let bytes: &'static [u8] = include_bytes!("../../static/geo/peru_mask.bin");
        assert_eq!(
            bytes.len(),
            meta.window.ncols * meta.window.nrows,
            "peru mask size"
        );
        assert!(
            (meta.window.cell - CELL).abs() < 1e-6,
            "peru mask cell size"
        );
        assert!(
            meta.departments.len() <= 255,
            "department index fits in one byte"
        );
        Mask {
            departments: meta
                .departments
                .into_iter()
                .map(|d| Department {
                    code: d.code,
                    name_es: d.name_es,
                    name_en: d.name_en,
                })
                .collect(),
            ncols: meta.window.ncols,
            nrows: meta.window.nrows,
            lon0: meta.window.lon0,
            lat_top: meta.window.lat_top,
            bytes,
        }
    })
}

pub fn departments() -> &'static [Department] {
    &mask().departments
}

pub fn series_id(dept: &Department) -> String {
    format!("precip_{}", dept.code)
}

/// Department containing a point, or the nearest department cell within `radius` cells
/// (coastal stations can sit just outside the 0.05° land mask).
pub fn department_at(lat: f64, lon: f64, radius: i64) -> Option<&'static Department> {
    let m = mask();
    let r0 = ((m.lat_top - lat) / CELL).round() as i64;
    let c0 = ((lon - m.lon0) / CELL).round() as i64;
    let mut best: Option<(i64, usize)> = None;
    for dr in -radius..=radius {
        for dc in -radius..=radius {
            let (r, c) = (r0 + dr, c0 + dc);
            if r < 0 || c < 0 || r >= m.nrows as i64 || c >= m.ncols as i64 {
                continue;
            }
            let d = m.bytes[r as usize * m.ncols + c as usize] as usize;
            let dist = dr * dr + dc * dc;
            if d < m.departments.len() && best.is_none_or(|(b, _)| dist < b) {
                best = Some((dist, d));
            }
        }
    }
    best.map(|(_, d)| &m.departments[d])
}

/// Window position inside the full grid, as (row0, col0).
fn window_offset() -> (usize, usize) {
    let m = mask();
    let row0 = ((FULL_LAT_TOP - m.lat_top) / CELL).round() as usize;
    let col0 = ((m.lon0 - FULL_LON0) / CELL).round() as usize;
    assert!(row0 + m.nrows <= FULL_NROWS, "peru window rows fit");
    assert!(col0 + m.ncols <= FULL_NCOLS, "peru window cols fit");
    (row0, col0)
}

// ---------------------------------------------------------------- parsing

fn frame_url(date: NaiveDate) -> String {
    format!(
        "{BASE}/{}/chirps-v3.0.prelim.{}.tif",
        date.format("%Y"),
        date.format("%Y.%m.%d")
    )
}

/// Decodes a CHIRPS GeoTIFF and returns the Peru window subset.
pub fn parse_frame(bytes: &[u8]) -> Result<Grid> {
    let mut dec = tiff::decoder::Decoder::new(Cursor::new(bytes)).context("opening TIFF")?;
    let (w, h) = dec.dimensions().context("reading TIFF dimensions")?;
    if (w as usize, h as usize) != (FULL_NCOLS, FULL_NROWS) {
        bail!("unexpected CHIRPS grid {w}x{h}, expected {FULL_NCOLS}x{FULL_NROWS}");
    }
    // Validate georeferencing when the tags are present (GDAL writes them).
    let scale = dec
        .get_tag_f64_vec(tiff::tags::Tag::ModelPixelScaleTag)
        .unwrap_or_default();
    if let Some(s) = scale.first()
        && (s - CELL).abs() > 1e-3
    {
        bail!("unexpected CHIRPS pixel scale {scale:?}");
    }
    let tie = dec
        .get_tag_f64_vec(tiff::tags::Tag::ModelTiepointTag)
        .unwrap_or_default();
    if tie.len() >= 6 {
        // Corner convention: top-left corner of pixel (0,0) at (-180, 60).
        if (tie[3] + 180.0).abs() > 1e-3 || (tie[4] - 60.0).abs() > 1e-3 {
            bail!("unexpected CHIRPS tiepoint {tie:?}");
        }
    }
    let img = dec.read_image().context("decoding TIFF image")?;
    let data: Vec<f32> = match img {
        tiff::decoder::DecodingResult::F32(v) => v,
        tiff::decoder::DecodingResult::F64(v) => v.into_iter().map(|x| x as f32).collect(),
        other => bail!("unexpected TIFF sample layout {other:?}"),
    };
    if data.len() != FULL_NCOLS * FULL_NROWS {
        bail!(
            "decoded {} cells, expected {}",
            data.len(),
            FULL_NCOLS * FULL_NROWS
        );
    }
    let m = mask();
    let (row0, col0) = window_offset();
    let mut sub = vec![f32::NAN; m.ncols * m.nrows];
    for r in 0..m.nrows {
        let src = (row0 + r) * FULL_NCOLS + col0;
        for c in 0..m.ncols {
            let v = data[src + c];
            // CHIRPS nodata is -9999; no real precipitation value is negative.
            if v >= 0.0 {
                sub[r * m.ncols + c] = v;
            }
        }
    }
    Ok(Grid {
        ncols: m.ncols,
        nrows: m.nrows,
        lon0: m.lon0,
        lat_top: m.lat_top,
        cell: CELL,
        data: sub,
    })
}

/// Simple mean of the non-missing cells in each department.
pub fn department_means(g: &Grid) -> Vec<Option<f64>> {
    let m = mask();
    assert_eq!(g.data.len(), m.bytes.len(), "grid matches mask");
    let mut sums = vec![0.0_f64; m.departments.len()];
    let mut counts = vec![0_usize; m.departments.len()];
    for (i, &d) in m.bytes.iter().enumerate() {
        let d = d as usize;
        if d >= m.departments.len() {
            continue;
        }
        let v = g.data[i];
        if !v.is_nan() {
            sums[d] += f64::from(v);
            counts[d] += 1;
        }
    }
    sums.iter()
        .zip(counts)
        .map(|(s, n)| (n > 0).then_some(s / n as f64))
        .collect()
}

// ---------------------------------------------------------------- fetching

pub fn grid_path(ctx: &Ctx, date: &str) -> PathBuf {
    ctx.cfg
        .data_dir
        .join("grids")
        .join(DATASET)
        .join(format!("{date}.bin"))
}

/// The most recent date whose frame exists on the server.
async fn latest_date(ctx: &Ctx) -> Result<NaiveDate> {
    let today = chrono::Utc::now().date_naive();
    for back in 0..PROBE_DAYS {
        let d = today - Duration::days(back);
        if fetch::head(ctx, &frame_url(d)).await?.is_success() {
            return Ok(d);
        }
    }
    bail!("no CHIRPS frame found in the last {PROBE_DAYS} days")
}

/// Downloads one frame. Returns None when the cached copy is still current.
async fn fetch_frame(ctx: &Ctx, date: NaiveDate) -> Result<Option<Grid>> {
    let url = frame_url(date);
    let (fetched, pending) = fetch::get(ctx, DATASET, &url).await?;
    match fetched {
        Fetched::Unchanged => {
            pending.commit(ctx)?;
            Ok(None)
        }
        Fetched::Changed(body) => {
            let grid = parse_frame(&body).with_context(|| format!("parsing CHIRPS {date}"))?;
            pending.commit(ctx)?;
            Ok(Some(grid))
        }
    }
}

/// Fetches missing frames (newest first) up to `limit`, plus a re-check of the newest
/// frame (preliminary pentad files are revised in place). Returns frames stored.
pub async fn sync(ctx: &Ctx, limit: usize) -> Result<usize> {
    let latest = latest_date(ctx).await?;
    let first = latest - Duration::days(ctx.cfg.precip_days - 1);
    let have: HashSet<String> = {
        let conn = ctx.db.get()?;
        let mut stmt = conn.prepare("SELECT date FROM grid_frame WHERE dataset=?1")?;
        stmt.query_map([DATASET], |r| r.get(0))?
            .collect::<rusqlite::Result<_>>()?
    };
    let mut todo: Vec<NaiveDate> = first
        .iter_days()
        .take_while(|d| *d <= latest)
        .filter(|d| !have.contains(&d.to_string()))
        .collect();
    if have.contains(&latest.to_string()) {
        todo.push(latest);
    }
    todo.sort_unstable();
    todo.dedup();

    let mut stored = 0;
    for date in todo.into_iter().rev().take(limit) {
        let grid = match fetch_frame(ctx, date).await {
            Ok(Some(g)) => g,
            Ok(None) => continue,
            Err(e) if stored > 0 => {
                tracing::warn!(%date, error = %format!("{e:#}"), "CHIRPS frame failed; will retry");
                break;
            }
            Err(e) => return Err(e),
        };
        let d = date.to_string();
        grid.save(&grid_path(ctx, &d))?;
        let means = department_means(&grid);
        let mut conn = ctx.db.get()?;
        for (dept, mean) in departments().iter().zip(means) {
            if let Some(v) = mean {
                let v = (v * 100.0).round() / 100.0;
                db::upsert_series(
                    &mut conn,
                    &series_id(dept),
                    DATASET,
                    "mm",
                    "daily",
                    &[(d.clone(), v)],
                )?;
            }
        }
        conn.execute(
            "INSERT OR REPLACE INTO grid_frame (dataset, date, created) VALUES (?1, ?2, ?3)",
            params![DATASET, d, db::now()],
        )?;
        stored += 1;
        // Be gentle with the CHC server.
        tokio::time::sleep(std::time::Duration::from_millis(500)).await;
    }

    prune(ctx, first)?;
    Ok(stored)
}

/// Removes frames older than the retention window (derived series are kept).
fn prune(ctx: &Ctx, first: NaiveDate) -> Result<()> {
    let conn = ctx.db.get()?;
    let old: Vec<String> = {
        let mut stmt =
            conn.prepare("SELECT date FROM grid_frame WHERE dataset=?1 AND date < ?2")?;
        stmt.query_map(params![DATASET, first.to_string()], |r| r.get(0))?
            .collect::<rusqlite::Result<_>>()?
    };
    for d in old {
        std::fs::remove_file(grid_path(ctx, &d)).ok();
        conn.execute(
            "DELETE FROM grid_frame WHERE dataset=?1 AND date=?2",
            params![DATASET, d],
        )?;
        // Forget the conditional-GET cache too, so a pruned date could be refetched.
        conn.execute(
            "DELETE FROM http_cache WHERE url=?1",
            [frame_url(NaiveDate::parse_from_str(&d, "%Y-%m-%d")?)],
        )?;
    }
    Ok(())
}

pub async fn run(ctx: &Ctx) -> Result<bool> {
    Ok(sync(ctx, PER_RUN).await? > 0)
}

// ---------------------------------------------------------------- tests

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Read;

    fn fixture() -> Vec<u8> {
        let path = format!(
            "{}/tests/fixtures/chirps_v3_20261020.tif.gz",
            env!("CARGO_MANIFEST_DIR")
        );
        let gz = std::fs::read(&path).expect("fixture present");
        let mut out = Vec::new();
        flate2::read::GzDecoder::new(&gz[..])
            .read_to_end(&mut out)
            .expect("fixture gunzips");
        out
    }

    #[test]
    fn parses_fixture_and_aggregates() {
        let g = parse_frame(&fixture()).unwrap();
        assert_eq!((g.ncols, g.nrows), (260, 370));
        assert!((g.lat_top - (-0.025)).abs() < 1e-6);
        assert!((g.lon0 - (-81.475)).abs() < 1e-6);
        // Inland Lima and the eastern jungle are real data; CHIRPS v3 (IMERG-based)
        // also covers the ocean, so nodata only appears outside the 60°S–60°N window.
        assert!(g.sample_nearest(-12.05, -76.9).is_some());
        assert!(g.sample_nearest(-3.75, -73.25).is_some());
        // Every department has at least one cell with data.
        let means = department_means(&g);
        assert_eq!(means.len(), 25);
        assert!(means.iter().all(|m| m.is_some()), "{means:?}");
    }

    #[test]
    fn mask_geometry() {
        // Known cells, checked against the committed mask (natural Earth boundaries).
        let m = mask();
        let dept_at = |lat: f64, lon: f64| -> Option<&str> {
            let c = ((lon - m.lon0) / CELL).round() as i64;
            let r = ((m.lat_top - lat) / CELL).round() as i64;
            if r < 0 || c < 0 || r >= m.nrows as i64 || c >= m.ncols as i64 {
                return None;
            }
            let d = m.bytes[r as usize * m.ncols + c as usize] as usize;
            (d < m.departments.len()).then(|| m.departments[d].code.as_str())
        };
        assert_eq!(dept_at(-3.57, -80.46), Some("tumbes"));
        assert_eq!(dept_at(-5.19, -80.63), Some("piura"));
        assert_eq!(dept_at(-12.05, -76.9), Some("lima"));
        assert_eq!(dept_at(-15.84, -70.02), Some("puno"));
        assert_eq!(dept_at(-18.05, -70.25), Some("tacna"));
        assert_eq!(dept_at(-3.75, -73.25), Some("loreto"));
        // Ocean just off the Lima coast is outside every department.
        assert_eq!(dept_at(-12.1, -77.3), None);
    }

    #[test]
    fn window_offsets_and_urls() {
        assert_eq!(window_offset(), (1200, 1970));
        let d = NaiveDate::from_ymd_opt(2026, 10, 20).unwrap();
        assert_eq!(
            frame_url(d),
            "https://data.chc.ucsb.edu/products/CHIRPS/v3.0/daily/prelim/sat/2026/chirps-v3.0.prelim.2026.10.20.tif"
        );
    }

    #[test]
    fn departments_are_unique_and_named() {
        let depts = departments();
        assert_eq!(depts.len(), 25);
        let mut codes: Vec<_> = depts.iter().map(|d| d.code.clone()).collect();
        codes.sort();
        codes.dedup();
        assert_eq!(codes.len(), 25);
        assert!(
            depts
                .iter()
                .all(|d| !d.name_es.is_empty() && !d.name_en.is_empty())
        );
    }
}
